import { join } from "path";

const testDir = "/tmp/hypothesis-yaml-validator/test-files";

console.log("=== HYP-001: Bun.glob() Behavior Testing ===\n");

// Create test YAML files
console.log("Creating test file structure...");
const files = [
  "config.yaml",
  "app.yml",
  "src/database.yaml",
  "src/logging.yaml",
  "config/prod.yaml",
  "config/dev.yml",
  "nested/deep/settings.yaml",
];

