import { describe, test, expect } from "bun:test";
import { validateYAML } from "./yaml-parser";

describe("yaml-parser", () => {
  describe("Valid YAML", () => {
    test("simple key-value pair", () => {
      const content = "name: John\nage: 30";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("nested structure", () => {
      const content = `person:
  name: John
  age: 30
  address:
    street: 123 Main St
    city: New York`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("quoted strings", () => {
      const content = `title: "Hello World"
description: 'This is a test'
special: "Value with: colon"`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("comments", () => {
      const content = `# This is a comment
name: John
# Another comment
age: 30`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("list items", () => {
      const content = `items:
  - apple
  - banana
  - cherry`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("mixed content", () => {
      const content = `name: Test
items:
  - item1
  - item2
metadata:
  created: 2026-01-01
  tags:
    - tag1
    - tag2`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("empty values", () => {
      const content = `key1:
key2: value
key3:`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("escaped quotes in strings", () => {
      const content = 'message: "He said \\"Hello\\""';
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });
  });

  describe("Indentation Errors", () => {
    test("inconsistent indentation (4 spaces vs 2)", () => {
      const content = `parent:
    child: value`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("indentation");
    });

    test("tab character detection", () => {
      const content = "parent:\n\tchild: value";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("indentation");
      expect(result.errors[0].message).toContain("tabs");
    });

    test("unexpected indentation jump", () => {
      const content = `parent:
  child1: value1
        child2: value2`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("indentation");
    });

    test("inconsistent indentation decrease", () => {
      const content = `parent:
  child:
    grandchild: value
   sibling: value`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("mixed tabs and spaces", () => {
      const content = "parent:\n  \tchild: value";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });

  describe("Syntax Errors", () => {
    test("unclosed double-quoted string", () => {
      const content = 'name: "John';
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("syntax");
      expect(result.errors[0].message).toContain("Unclosed");
    });

    test("unclosed single-quoted string", () => {
      const content = "name: 'John";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("syntax");
    });

    test("unbalanced closing bracket", () => {
      const content = "items: [apple, banana]";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("unbalanced opening bracket", () => {
      const content = "items: [apple, banana";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("syntax");
    });

    test("unbalanced opening brace", () => {
      const content = "data: {key: value";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("unbalanced closing brace", () => {
      const content = "data: key: value}";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("missing key before colon", () => {
      const content = ": value";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].type).toBe("structure");
    });

    test("unclosed parenthesis", () => {
      const content = "data: (value1, value2";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("mismatched brackets", () => {
      const content = "data: [value1, value2}";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });

  describe("Edge Cases", () => {
    test("empty file", () => {
      const content = "";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("only whitespace", () => {
      const content = "   \n\n  \n  ";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("only comments", () => {
      const content = "# Comment 1\n# Comment 2\n# Comment 3";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("CRLF line endings", () => {
      const content = "name: John\r\nage: 30\r\ncity: NYC";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("mixed LF and CRLF", () => {
      const content = "name: John\r\nage: 30\ncity: NYC";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("single line", () => {
      const content = "name: John";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("deeply nested structure", () => {
      const content = `level1:
  level2:
    level3:
      level4:
        level5:
          level6: value`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("large file simulation (many lines)", () => {
      let content = "";
      for (let i = 0; i < 1000; i++) {
        content += `key${i}: value${i}\n`;
      }
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("line with trailing whitespace", () => {
      const content = "name: John   \nage: 30  ";
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("value with special characters", () => {
      const content = 'message: "~!@#$%^&*()_+-=[]{}|;:,.<>?"';
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });
  });

  describe("Real-World Scenarios", () => {
    test("kubernetes config file", () => {
      const content = `apiVersion: v1
kind: Pod
metadata:
  name: test-pod
  labels:
    app: test
spec:
  containers:
    - name: test-container
      image: test:latest
      ports:
        - containerPort: 8080`;
      const result = validateYAML(content, "k8s.yaml");
      expect(result.valid).toBe(true);
    });

    test("docker compose config", () => {
      const content = `version: '3'
services:
  web:
    image: nginx:latest
    ports:
      - "80:80"
    environment:
      - DEBUG=false`;
      const result = validateYAML(content, "docker-compose.yaml");
      expect(result.valid).toBe(true);
    });

    test("broken config with multiple errors", () => {
      const content = `name: Test
data: {unclosed
items:
    - item1
  - item2`;
      const result = validateYAML(content, "broken.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("deeply nested kubernetes error", () => {
      const content = `apiVersion: v1
kind: Pod
metadata:
  name: test-pod
spec:
  containers:
    - name: test
      resources:
        limits:
            memory: 512Mi`;
      const result = validateYAML(content, "k8s.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("config with numbers and booleans", () => {
      const content = `count: 42
enabled: true
ratio: 3.14
name: "test"`;
      const result = validateYAML(content, "config.yaml");
      expect(result.valid).toBe(true);
    });

    test("config with special yaml characters in quoted strings", () => {
      const content = `title: "Version 1.0: A & B"
description: "Contains | pipe and @ symbol"`;
      const result = validateYAML(content, "config.yaml");
      expect(result.valid).toBe(true);
    });
  });

  describe("Error Reporting", () => {
    test("error includes correct file path", () => {
      const content = "name: 'unclosed";
      const filePath = "config/app.yaml";
      const result = validateYAML(content, filePath);
      expect(result.file).toBe(filePath);
      expect(result.errors[0].file).toBe(filePath);
    });

    test("error includes correct line number", () => {
      const content = `line1: value1
line2: value2
line3: "unclosed`;
      const result = validateYAML(content, "test.yaml");
      expect(result.errors[0].line).toBe(3);
    });

    test("error includes column information", () => {
      const content = "name: 'unclosed";
      const result = validateYAML(content, "test.yaml");
      expect(result.errors[0].column).toBeGreaterThan(0);
    });

    test("error type is set correctly", () => {
      const contentSyntax = "name: 'unclosed";
      const resultSyntax = validateYAML(contentSyntax, "test.yaml");
      expect(resultSyntax.errors[0].type).toBe("syntax");

      const contentIndent = "parent:\n    child: value";
      const resultIndent = validateYAML(contentIndent, "test.yaml");
      expect(resultIndent.errors[0].type).toBe("indentation");

      const contentStructure = ": missing-key";
      const resultStructure = validateYAML(contentStructure, "test.yaml");
      expect(resultStructure.errors[0].type).toBe("structure");
    });

    test("error message is descriptive", () => {
      const content = "name: 'unclosed";
      const result = validateYAML(content, "test.yaml");
      expect(result.errors[0].message).toBeDefined();
      expect(result.errors[0].message.length).toBeGreaterThan(0);
    });
  });

  describe("Complex Nested Cases", () => {
    test("properly formatted nested list", () => {
      const content = `items:
  - name: item1
    price: 10
  - name: item2
    price: 20`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("inline flow style", () => {
      const content = `items: [apple, banana, cherry]
person: {name: John, age: 30}`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("quotes within quotes", () => {
      const content = `message: "He said 'Hello World'"
alternate: 'She said "Goodbye"'`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("multiple colons in quoted string", () => {
      const content = `url: "http://example.com:8080/path"
time: "12:30:45"`;
      const result = validateYAML(content, "test.yaml");
      expect(result.valid).toBe(true);
    });
  });

  describe("Return Value Structure", () => {
    test("returns ValidationResult object", () => {
      const content = "test: value";
