     8→ * - Structure errors (invalid YAML keys, missing colons)
     9→ *
    10→ * The parser tokenizes input line-by-line and validates against YAML structural rules.
    11→ * It returns structured error information with file path, line number, column, and message.
    12→ *
    13→ * Limitations:
    14→ * - Advanced YAML features (anchors/aliases, custom tags) are not supported
    15→ * - Schema validation is not supported (basic syntax only)
    16→ * - Complex nested structures may have edge cases
    17→ */
    18→
    19→/**
    20→ * Represents a single YAML validation error.
    21→ */
    22→export type YAMLError = {
    23→  file: string;
    24→  line: number;
    25→  column: number;
    26→  type: "syntax" | "indentation" | "structure";
    27→  message: string;
    28→};
    29→
    30→/**
    31→ * Represents the result of validating a single YAML file.
    32→ */
    33→export type ValidationResult = {
    34→  file: string;
    35→  valid: boolean;
    36→  errors: YAMLError[];
    37→};
    38→
    39→/**
    40→ * Validates YAML content for syntax correctness and structural integrity.
    41→ *
    42→ * Algorithm:
    43→ * 1. Normalize line endings (CRLF -> LF)
    44→ * 2. Split content into lines
    45→ * 3. Track indentation state using a stack of indentation levels
    46→ * 4. For each line:
    47→ *    - Skip empty lines and comments (lines starting with #)
    48→ *    - Validate indentation (spaces only, consistent depth)
    49→ *    - Parse key-value pairs (check for colons, quotes)
    50→ *    - Check for balanced brackets/braces
    51→ * 5. Return structured validation result with accurate line/column numbers (1-indexed)
    52→ *
    53→ * @param content - The YAML file content as a string
    54→ * @param filePath - The file path for error reporting
    55→ * @returns ValidationResult with valid flag and errors array
    56→ */
    57→export function validateYAML(
    58→  content: string,
    59→  filePath: string
    60→): ValidationResult {
    61→  const errors: YAMLError[] = [];
    62→
    63→  // Normalize line endings
    64→  const normalized = content.replace(/\r\n/g, "\n");
    65→  const lines = normalized.split("\n");
    66→
    67→  // Track indentation state
    68→  const indentStack: number[] = [0]; // Start with base indentation level 0
    69→  let bracketStack: string[] = []; // Track open brackets/braces/parentheses
    70→
    71→  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    72→    const line = lines[lineNum];
    73→    const lineNumber = lineNum + 1; // 1-indexed for user display
    74→
    75→    // Skip empty lines
    76→    if (line.trim().length === 0) {
    77→      continue;
    78→    }
    79→
    80→    // Skip comments
    81→    if (line.trim().startsWith("#")) {
    82→      continue;
    83→    }
    84→
    85→    // Check for tabs (YAML should use spaces)
    86→    if (line.includes("\t")) {
    87→      errors.push({
    88→        file: filePath,
    89→        line: lineNumber,
    90→        column: line.indexOf("\t") + 1,
    91→        type: "indentation",
    92→        message: "YAML does not support tabs; use spaces only",
    93→      });
    94→      continue;
    95→    }
    96→
    97→    // Calculate indentation
    98→    const leadingSpaces = line.match(/^( *)/)?.[0]?.length ?? 0;
    99→    const trimmedLine = line.trim();
   100→
   101→    // Validate indentation consistency
   102→    const currentIndent = indentStack[indentStack.length - 1];
   103→    const indentChange = leadingSpaces - currentIndent;
   104→
   105→    // Indentation should increase or decrease by consistent amounts (usually 2 spaces)
   106→    if (indentChange > 0) {
   107→      // Indentation increased - allow reasonable increase (1-8 spaces typically)
   108→      if (indentChange > 8) {
   109→        errors.push({
   110→          file: filePath,
   111→          line: lineNumber,
   112→          column: leadingSpaces + 1,
   113→          type: "indentation",
   114→          message: `Unexpected indentation increase of ${indentChange} spaces`,
   115→        });
   116→        continue;
   117→      }
   118→      indentStack.push(leadingSpaces);
   119→    } else if (indentChange < 0) {
   120→      // Indentation decreased - pop stack until we find matching level
   121→      while (
   122→        indentStack.length > 1 &&
   123→        indentStack[indentStack.length - 1] > leadingSpaces
   124→      ) {
   125→        indentStack.pop();
   126→      }
   127→      // Verify we found matching indentation level
   128→      if (indentStack[indentStack.length - 1] !== leadingSpaces) {
   129→        errors.push({
   130→          file: filePath,
   131→          line: lineNumber,
   132→          column: leadingSpaces + 1,
   133→          type: "indentation",
   134→          message: `Inconsistent indentation; expected multiple of base indent`,
   135→        });
   136→        continue;
   137→      }
   138→    }
   139→
   140→    // Validate syntax: check for balanced quotes and brackets
   141→    const quoteError = validateQuotesAndBrackets(trimmedLine, lineNumber, filePath);
   142→    if (quoteError) {
   143→      errors.push(quoteError);
   144→      continue;
   145→    }
   146→
   147→    // Validate key-value pair structure if line contains colons
   148→    if (trimmedLine.includes(":")) {
   149→      const keyValueError = validateKeyValuePair(trimmedLine, lineNumber, filePath);
   150→      if (keyValueError) {
   151→        errors.push(keyValueError);
   152→      }
   153→    }
   154→  }
   155→
   156→  return {
   157→    file: filePath,
   158→    valid: errors.length === 0,
   159→    errors,
   160→  };
   161→}
