   210→            file: filePath,
   211→            line: lineNumber,
   212→            column: i + 1,
   213→            type: "syntax",
   214→            message: "Unbalanced closing bracket ]",
   215→          };
   216→        }
   217→        stack.pop();
   218→      } else if (char === ")") {
