   220→          return {
   221→            file: filePath,
   222→            line: lineNumber,
   223→            column: i + 1,
   224→            type: "syntax",
   225→            message: "Unbalanced closing parenthesis )",
   226→          };
   227→        }
   228→        stack.pop();
   229→      }
   230→    }
   231→  }
   232→
   233→  // Check for unclosed quotes
   234→  if (inSingleQuote) {
   235→    return {
   236→      file: filePath,
   237→      line: lineNumber,
   238→      column: line.length + 1,
   239→      type: "syntax",
   240→      message: "Unclosed single-quoted string",
   241→    };
   242→  }
