/**
 * YAML CLI - Command-line interface orchestration for YAML validation
 *
 * This module provides CLI functionality for the YAML validator, including:
 * - File and glob pattern resolution using Bun.glob()
 * - Batch file validation with graceful error handling
 * - Output formatting with clear success/failure indicators
 * - Summary generation for multiple file validation results
 *
 * The module orchestrates the validation workflow by accepting file patterns,
 * expanding them via glob matching, reading files, validating content, and
 * formatting results for console output.
 */

import { validateYAML, ValidationResult } from "./yaml-parser";

/**
 * Resolves file paths and glob patterns to concrete file paths.
 *
 * Uses Bun.glob() to expand glob patterns (*, **, ?) and deduplicates results.
 * Supports mixed input of direct file paths and glob patterns.
 *
 * @param patterns - Array of file paths or glob patterns (e.g., ["config.yaml", "src/**\/*.yaml"])
 * @returns Promise resolving to deduplicated array of file paths
 * @throws Error if no files match the provided patterns
 */
export async function resolveFiles(patterns: string[]): Promise<string[]> {
  const resolvedSet = new Set<string>();

  for (const pattern of patterns) {
    try {
      // Check if pattern contains glob characters
      if (pattern.includes("*") || pattern.includes("?")) {
        // Use Bun.glob() for pattern expansion
        const globResults = await Bun.glob(pattern);
        for await (const file of globResults) {
          resolvedSet.add(file);
        }
      } else {
        // Treat as direct file path
        resolvedSet.add(pattern);
      }
    } catch (error) {
      // Glob expansion failed - could be invalid pattern or no matches
      // Continue with other patterns rather than failing completely
      continue;
    }
  }

  const resolved = Array.from(resolvedSet).sort();

  if (resolved.length === 0) {
    throw new Error(
      `No files matched patterns: ${patterns.join(", ")}`
    );
  }

  return resolved;
}

/**
 * Validates an array of YAML files and returns validation results.
 *
 * Reads each file using Bun.file() and calls validateYAML() for content validation.
 * Handles file read errors gracefully (missing files, permission errors) and
 * continues processing remaining files.
 *
 * @param filePaths - Array of file paths to validate
 * @returns Promise resolving to array of ValidationResult objects (one per file)
 */
export async function validateFiles(filePaths: string[]): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  for (const filePath of filePaths) {
    try {
      // Read file using Bun.file()
      const file = Bun.file(filePath);
      const exists = await file.exists();

      if (!exists) {
        // File does not exist - create error result
        results.push({
          file: filePath,
          valid: false,
          errors: [
            {
              file: filePath,
              line: 0,
              column: 0,
              type: "syntax",
              message: "File not found",
            },
          ],
        });
        continue;
      }

      const content = await file.text();
      const result = validateYAML(content, filePath);
      results.push(result);
    } catch (error) {
      // Handle file read errors (permission denied, I/O errors, etc.)
      const errorMessage =
        error instanceof Error ? error.message : String(error);

      results.push({
        file: filePath,
        valid: false,
        errors: [
          {
            file: filePath,
            line: 0,
            column: 0,
            type: "syntax",
            message: `Error reading file: ${errorMessage}`,
          },
        ],
      });
    }
  }

  return results;
}

/**
 * Formats validation results for console output.
 *
 * Produces human-readable output with:
 * - Success indicator (✓) for valid files
 * - Error indicator (✗) for invalid files
 * - Detailed error information (line, column, message) for each error
 *
 * @param results - Array of ValidationResult objects from validateFiles()
 * @returns Formatted string ready for console output
 */
export function formatOutput(results: ValidationResult[]): string {
  const lines: string[] = [];

  for (const result of results) {
    if (result.valid) {
      // Valid file - show success indicator
      lines.push(`✓ ${result.file}`);
    } else {
      // Invalid file - show error indicator and details
      lines.push(`✗ ${result.file}`);
      for (const error of result.errors) {
        lines.push(`  Line ${error.line}, Column ${error.column}: ${error.message}`);
      }
    }
  }

  return lines.join("\n");
}

/**
 * Generates a summary of validation results.
 *
 * Counts passed (valid) and failed (invalid) files and returns summary counts.
 *
 * @param results - Array of ValidationResult objects from validateFiles()
 * @returns Object with passed, failed, and total file counts
 */
export function getSummary(
  results: ValidationResult[]
): { passed: number; failed: number; total: number } {
  const passed = results.filter((r) => r.valid).length;
  const failed = results.filter((r) => !r.valid).length;

  return {
    passed,
    failed,
    total: results.length,
  };
}

import { describe, test, expect, beforeEach, afterEach } from "bun:test";
import { resolveFiles, validateFiles, formatOutput, getSummary } from "./yaml-cli";
import { join } from "path";
import { realpathSync } from "fs";

// Temporary directory for test fixtures
const tempDir = "/tmp/yaml-cli-test-" + Math.random().toString(36).substring(7);

beforeEach(async () => {
  // Create temporary directory if it doesn't exist
  await Bun.write(join(tempDir, ".gitkeep"), "");
  const tempDirPath = dirname(join(tempDir, ".gitkeep"));
  // Directory will be created by Bun.write
});

afterEach(async () => {
  // Clean up temporary files
  try {
    const tempDirPath = tempDir;
    const files = await Bun.glob(join(tempDirPath, "**/*"));
    for await (const file of files) {
      try {
        Bun.file(file).delete?.() || (await Bun.write(file, ""));
      } catch (e) {
        // Ignore cleanup errors
      }
    }
  } catch (e) {
    // Ignore cleanup errors
  }
});

// Helper function to get directory from path
function dirname(path: string): string {
  const parts = path.split("/");
  return parts.slice(0, -1).join("/");
}

describe("resolveFiles", () => {
  test("resolves single file path", async () => {
    const testFile = join(tempDir, "test.yaml");
    await Bun.write(testFile, "key: value\n");

    const resolved = await resolveFiles([testFile]);

    expect(resolved).toHaveLength(1);
    expect(resolved[0]).toBe(testFile);
  });

  test("resolves multiple file paths", async () => {
    const file1 = join(tempDir, "file1.yaml");
    const file2 = join(tempDir, "file2.yaml");
    await Bun.write(file1, "key: value\n");
    await Bun.write(file2, "other: data\n");

    const resolved = await resolveFiles([file1, file2]);

    expect(resolved).toHaveLength(2);
    expect(resolved).toContain(file1);
    expect(resolved).toContain(file2);
  });

  test("resolves glob pattern with asterisk", async () => {
    const file1 = join(tempDir, "config1.yaml");
    const file2 = join(tempDir, "config2.yaml");
    const file3 = join(tempDir, "other.txt");
    await Bun.write(file1, "key: value\n");
    await Bun.write(file2, "other: data\n");
    await Bun.write(file3, "not yaml\n");

    const pattern = join(tempDir, "*.yaml");
    const resolved = await resolveFiles([pattern]);

    expect(resolved.length).toBeGreaterThanOrEqual(2);
    expect(resolved.some((f) => f.includes("config1.yaml"))).toBe(true);
    expect(resolved.some((f) => f.includes("config2.yaml"))).toBe(true);
  });

  test("deduplicates file paths", async () => {
    const testFile = join(tempDir, "test.yaml");
    await Bun.write(testFile, "key: value\n");

    const resolved = await resolveFiles([testFile, testFile]);

    expect(resolved).toHaveLength(1);
    expect(resolved[0]).toBe(testFile);
  });

  test("throws error when no files match patterns", async () => {
    const pattern = join(tempDir, "nonexistent-*.yaml");

    try {
      await resolveFiles([pattern]);
      expect.unreachable("Should have thrown error");
    } catch (error) {
      if (error instanceof Error) {
        expect(error.message).toContain("No files matched");
      }
    }
  });

  test("returns sorted file paths", async () => {
    const file1 = join(tempDir, "z-file.yaml");
    const file2 = join(tempDir, "a-file.yaml");
    const file3 = join(tempDir, "m-file.yaml");
    await Bun.write(file1, "z: value\n");
    await Bun.write(file2, "a: value\n");
    await Bun.write(file3, "m: value\n");

    const resolved = await resolveFiles([file1, file2, file3]);

    expect(resolved[0]).toContain("a-file");
    expect(resolved[1]).toContain("m-file");
    expect(resolved[2]).toContain("z-file");
  });
});

describe("validateFiles", () => {
  test("validates valid YAML file", async () => {
    const testFile = join(tempDir, "valid.yaml");
    await Bun.write(testFile, "key: value\nother: data\n");

    const results = await validateFiles([testFile]);

    expect(results).toHaveLength(1);
    expect(results[0].valid).toBe(true);
    expect(results[0].errors).toHaveLength(0);
  });

  test("detects invalid YAML file", async () => {
    const testFile = join(tempDir, "invalid.yaml");
    await Bun.write(testFile, 'key: "unclosed string\n');

    const results = await validateFiles([testFile]);

    expect(results).toHaveLength(1);
    expect(results[0].valid).toBe(false);
    expect(results[0].errors.length).toBeGreaterThan(0);
  });

  test("processes multiple files", async () => {
    const file1 = join(tempDir, "valid1.yaml");
    const file2 = join(tempDir, "invalid1.yaml");
    const file3 = join(tempDir, "valid2.yaml");
    await Bun.write(file1, "key: value\n");
    await Bun.write(file2, 'broken: "unclosed\n');
    await Bun.write(file3, "other: data\n");

    const results = await validateFiles([file1, file2, file3]);

    expect(results).toHaveLength(3);
    expect(results[0].valid).toBe(true);
    expect(results[1].valid).toBe(false);
    expect(results[2].valid).toBe(true);
  });

  test("handles file not found", async () => {
    const missingFile = join(tempDir, "missing.yaml");

    const results = await validateFiles([missingFile]);

