/**
 * Resolves file paths and glob patterns to concrete file paths.
 *
 * Uses Bun.glob() to expand glob patterns (*, **, ?) and deduplicates results.
 * Supports mixed input of direct file paths and glob patterns.
 *
 * @param patterns - Array of file paths or glob patterns (e.g., ["config.yaml", "src/**\/*.yaml"])
 * @returns Promise resolving to deduplicated array of file paths
 * @throws Error if no files match the provided patterns
 */
export async function resolveFiles(patterns: string[]): Promise<string[]> {
  const resolvedSet = new Set<string>();

  for (const pattern of patterns) {
    try {
      // Check if pattern contains glob characters
      if (pattern.includes("*") || pattern.includes("?")) {
        // Use Bun.glob() for pattern expansion
        const globResults = await Bun.glob(pattern);
        for await (const file of globResults) {
          resolvedSet.add(file);
        }
      } else {
        // Treat as direct file path
        resolvedSet.add(pattern);
      }
    } catch (error) {
      // Glob expansion failed - could be invalid pattern or no matches
      // Continue with other patterns rather than failing completely
      continue;
    }
  }

  const resolved = Array.from(resolvedSet).sort();

  if (resolved.length === 0) {
    throw new Error(
      `No files matched patterns: ${patterns.join(", ")}`
    );
  }

  return resolved;
}

