     2→ * YAML Parser - Basic YAML syntax validation module
     3→ *
     4→ * This module provides lightweight YAML syntax validation using a hand-rolled parser.
     5→ * It detects common YAML errors including:
     6→ * - Indentation errors (tabs, inconsistent depths, unexpected changes)
     7→ * - Syntax errors (unclosed quotes, unbalanced brackets/braces, malformed key-value pairs)
     8→ * - Structure errors (invalid YAML keys, missing colons)
     9→ *
    10→ * The parser tokenizes input line-by-line and validates against YAML structural rules.
    11→ * It returns structured error information with file path, line number, column, and message.
    12→ *
    13→ * Limitations:
    14→ * - Advanced YAML features (anchors/aliases, custom tags) are not supported
    15→ * - Schema validation is not supported (basic syntax only)
    16→ * - Complex nested structures may have edge cases
    17→ */
    18→
    19→/**
    20→ * Represents a single YAML validation error.
    21→ */
    22→export type YAMLError = {
    23→  file: string;
    24→  line: number;
    25→  column: number;
    26→  type: "syntax" | "indentation" | "structure";
    27→  message: string;
    28→};
    29→
    30→/**
    31→ * Represents the result of validating a single YAML file.
    32→ */
    33→export type ValidationResult = {
    34→  file: string;
    35→  valid: boolean;
    36→  errors: YAMLError[];
    37→};
    38→
    39→/**
    40→ * Validates YAML content for syntax correctness and structural integrity.
    41→ *
    42→ * Algorithm:
    43→ * 1. Normalize line endings (CRLF -> LF)
    44→ * 2. Split content into lines
    45→ * 3. Track indentation state using a stack of indentation levels
    46→ * 4. For each line:
    47→ *    - Skip empty lines and comments (lines starting with #)
    48→ *    - Validate indentation (spaces only, consistent depth)
    49→ *    - Parse key-value pairs (check for colons, quotes)
    50→ *    - Check for balanced brackets/braces
    51→ * 5. Return structured validation result with accurate line/column numbers (1-indexed)
    52→ *
    53→ * @param content - The YAML file content as a string
    54→ * @param filePath - The file path for error reporting
    55→ * @returns ValidationResult with valid flag and errors array
    56→ */
    57→export function validateYAML(
    58→  content: string,
    59→  filePath: string
    60→): ValidationResult {
    61→  const errors: YAMLError[] = [];
    62→
    63→  // Normalize line endings
    64→  const normalized = content.replace(/\r\n/g, "\n");
    65→  const lines = normalized.split("\n");
    66→
    67→  // Track indentation state
    68→  const indentStack: number[] = [0]; // Start with base indentation level 0
    69→  let bracketStack: string[] = []; // Track open brackets/braces/parentheses
    70→
    71→  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    72→    const line = lines[lineNum];
    73→    const lineNumber = lineNum + 1; // 1-indexed for user display
    74→
    75→    // Skip empty lines
    76→    if (line.trim().length === 0) {
    77→      continue;
    78→    }
    79→
    80→    // Skip comments
    81→    if (line.trim().startsWith("#")) {
    82→      continue;
    83→    }
    84→
    85→    // Check for tabs (YAML should use spaces)
    86→    if (line.includes("\t")) {
    87→      errors.push({
    88→        file: filePath,
    89→        line: lineNumber,
    90→        column: line.indexOf("\t") + 1,
    91→        type: "indentation",
    92→        message: "YAML does not support tabs; use spaces only",
    93→      });
    94→      continue;
    95→    }
    96→
    97→    // Calculate indentation
    98→    const leadingSpaces = line.match(/^( *)/)?.[0]?.length ?? 0;
    99→    const trimmedLine = line.trim();
   100→
   101→    // Validate indentation consistency
   102→    const currentIndent = indentStack[indentStack.length - 1];
   103→    const indentChange = leadingSpaces - currentIndent;
   104→
   105→    // Indentation should increase or decrease by consistent amounts (usually 2 spaces)
   106→    if (indentChange > 0) {
   107→      // Indentation increased - allow reasonable increase (1-8 spaces typically)
   108→      if (indentChange > 8) {
   109→        errors.push({
   110→          file: filePath,
   111→          line: lineNumber,
   112→          column: leadingSpaces + 1,
   113→          type: "indentation",
   114→          message: `Unexpected indentation increase of ${indentChange} spaces`,
   115→        });
   116→        continue;
   117→      }
   118→      indentStack.push(leadingSpaces);
   119→    } else if (indentChange < 0) {
   120→      // Indentation decreased - pop stack until we find matching level
   121→      while (
   122→        indentStack.length > 1 &&
   123→        indentStack[indentStack.length - 1] > leadingSpaces
   124→      ) {
   125→        indentStack.pop();
   126→      }
   127→      // Verify we found matching indentation level
   128→      if (indentStack[indentStack.length - 1] !== leadingSpaces) {
   129→        errors.push({
   130→          file: filePath,
   131→          line: lineNumber,
   132→          column: leadingSpaces + 1,
   133→          type: "indentation",
   134→          message: `Inconsistent indentation; expected multiple of base indent`,
   135→        });
   136→        continue;
   137→      }
   138→    }
   139→
   140→    // Validate syntax: check for balanced quotes and brackets
   141→    const quoteError = validateQuotesAndBrackets(trimmedLine, lineNumber, filePath);
   142→    if (quoteError) {
   143→      errors.push(quoteError);
   144→      continue;
   145→    }
   146→
   147→    // Validate key-value pair structure if line contains colons
   148→    if (trimmedLine.includes(":")) {
   149→      const keyValueError = validateKeyValuePair(trimmedLine, lineNumber, filePath);
   150→      if (keyValueError) {
   151→        errors.push(keyValueError);
   152→      }
   153→    }
   154→  }
   155→
   156→  return {
   157→    file: filePath,
   158→    valid: errors.length === 0,
   159→    errors,
   160→  };
   161→}
   162→
   163→/**
   164→ * Validates quotes and bracket balancing in a line.
   165→ * Returns an error if quotes are unclosed or brackets are unbalanced.
   166→ */
   167→function validateQuotesAndBrackets(
   168→  line: string,
   169→  lineNumber: number,
   170→  filePath: string
   171→): YAMLError | null {
   172→  const stack: string[] = [];
   173→  let inSingleQuote = false;
   174→  let inDoubleQuote = false;
   175→
   176→  for (let i = 0; i < line.length; i++) {
   177→    const char = line[i];
   178→    const prevChar = i > 0 ? line[i - 1] : "";
   179→
   180→    // Handle escape sequences in quoted strings
   181→    if (prevChar === "\\") {
   182→      continue; // Skip escaped characters
   183→    }
   184→
   185→    // Toggle quote states
   186→    if (char === '"' && !inSingleQuote) {
   187→      inDoubleQuote = !inDoubleQuote;
   188→    } else if (char === "'" && !inDoubleQuote) {
   189→      inSingleQuote = !inSingleQuote;
   190→    }
   191→
   192→    // Only check brackets outside of quoted strings
   193→    if (!inSingleQuote && !inDoubleQuote) {
   194→      if (char === "{" || char === "[" || char === "(") {
   195→        stack.push(char);
   196→      } else if (char === "}") {
   197→        if (stack.length === 0 || stack[stack.length - 1] !== "{") {
   198→          return {
   199→            file: filePath,
   200→            line: lineNumber,
   201→            column: i + 1,
   202→            type: "syntax",
   203→            message: "Unbalanced closing brace }",
   204→          };
   205→        }
   206→        stack.pop();
   207→      } else if (char === "]") {
   208→        if (stack.length === 0 || stack[stack.length - 1] !== "[") {
   209→          return {
   210→            file: filePath,
   211→            line: lineNumber,
   212→            column: i + 1,
   213→            type: "syntax",
   214→            message: "Unbalanced closing bracket ]",
   215→          };
   216→        }
   217→        stack.pop();
   218→      } else if (char === ")") {
   219→        if (stack.length === 0 || stack[stack.length - 1] !== "(") {
   220→          return {
   221→            file: filePath,
   222→            line: lineNumber,
   223→            column: i + 1,
   224→            type: "syntax",
   225→            message: "Unbalanced closing parenthesis )",
   226→          };
   227→        }
   228→        stack.pop();
   229→      }
   230→    }
   231→  }
   232→
   233→  // Check for unclosed quotes
   234→  if (inSingleQuote) {
   235→    return {
   236→      file: filePath,
   237→      line: lineNumber,
   238→      column: line.length + 1,
   239→      type: "syntax",
   240→      message: "Unclosed single-quoted string",
   241→    };
   242→  }
   243→  if (inDoubleQuote) {
   244→    return {
   245→      file: filePath,
   246→      line: lineNumber,
   247→      column: line.length + 1,
   248→      type: "syntax",
   249→      message: "Unclosed double-quoted string",
   250→    };
   251→  }
   252→
   253→  // Check for unclosed brackets
   254→  if (stack.length > 0) {
   255→    const unclosed = stack[stack.length - 1];
   256→    const closingChar = unclosed === "{" ? "}" : unclosed === "[" ? "]" : ")";
   257→    return {
   258→      file: filePath,
   259→      line: lineNumber,
   260→      column: line.length + 1,
   261→      type: "syntax",
   262→      message: `Unclosed bracket/brace; expected ${closingChar}`,
   263→    };
   264→  }
   265→
   266→  return null;
   267→}
   268→
   269→/**
   270→ * Validates key-value pair structure.
   271→ * YAML key-value pairs should have format: key: value
   272→ * Returns an error if structure is invalid.
   273→ */
   274→function validateKeyValuePair(
   275→  line: string,
   276→  lineNumber: number,
   277→  filePath: string
   278→): YAMLError | null {
   279→  // Find the first colon not inside quotes
   280→  let inSingleQuote = false;
   281→  let inDoubleQuote = false;
   282→  let colonPos = -1;
   283→
   284→  for (let i = 0; i < line.length; i++) {
   285→    const char = line[i];
   286→    const prevChar = i > 0 ? line[i - 1] : "";
   287→
   288→    // Skip escaped characters
   289→    if (prevChar === "\\") {
   290→      continue;
   291→    }
   292→
   293→    // Track quote states
   294→    if (char === '"' && !inSingleQuote) {
   295→      inDoubleQuote = !inDoubleQuote;
   296→    } else if (char === "'" && !inDoubleQuote) {
   297→      inSingleQuote = !inSingleQuote;
   298→    }
   299→
   300→    // Find unquoted colon
   301→    if (char === ":" && !inSingleQuote && !inDoubleQuote) {
   302→      colonPos = i;
   303→      break;
   304→    }
   305→  }
   306→
   307→  // If there's a colon, ensure there's something before it
   308→  if (colonPos >= 0) {
   309→    const keyPart = line.substring(0, colonPos).trim();
   310→    if (keyPart.length === 0) {
   311→      return {
   312→        file: filePath,
   313→        line: lineNumber,
   314→        column: colonPos + 1,
   315→        type: "structure",
   316→        message: "Key-value pair missing key before colon",
   317→      };
   318→    }
   319→
   320→    // Check for invalid key characters (keys shouldn't have certain symbols)
   321→    if (
   322→      keyPart.startsWith("-") &&
   323→      keyPart !== "-" &&
   324→      keyPart[1] !== " " &&
   325→      keyPart[1] !== "\t"
   326→    ) {
   327→      // This is OK for list items
   328→    }
   329→  }
   330→
   331→  return null;
   332→}
