/**
 * Integration tests for the YAML validator command.
 *
 * These tests invoke the yaml:validate script via the `bun` command and verify:
 * - Exit code behavior (0 on success, 1 on failure)
 * - Output formatting and accuracy
 * - Glob pattern expansion and file resolution
 * - Error reporting with line/column information
 *
 * Tests use temporary YAML files created during test setup and cleaned up after.
 */

import { describe, test, expect, beforeAll, afterAll } from "bun:test";
import { $ } from "bun";
import fs from "fs";
import path from "path";

/**
 * Temporary directory for test fixtures.
 * Created before tests, cleaned up after.
 */
let testDir: string;

/**
 * Helper to create a temporary test file with YAML content.
 */
function createTestFile(
  filename: string,
  content: string
): string {
  const filePath = path.join(testDir, filename);
  const dirPath = path.dirname(filePath);

  // Create subdirectories if needed
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }

  fs.writeFileSync(filePath, content);
  return filePath;
}

/**
 * Helper to run the yaml:validate script via bun command.
 * Returns { exitCode, stdout, stderr }.
 */
async function runValidator(args: string[]): Promise<{
  exitCode: number;
  stdout: string;
  stderr: string;
}> {
  try {
    const cmd = `bun run yaml:validate ${args.join(" ")}`;
    const output = await $`bun run yaml:validate ${args}`.text();

    return {
      exitCode: 0,
      stdout: output,
      stderr: "",
    };
  } catch (error) {
    // Bun throws on non-zero exit; we catch and extract details
    const errorOutput =
      error instanceof Error ? error.message : String(error);

    // Try to parse exit code from error message
    const exitCodeMatch = errorOutput.match(/exited with code (\d+)/);
    const exitCode = exitCodeMatch ? parseInt(exitCodeMatch[1], 10) : 1;

    return {
      exitCode,
      stdout: errorOutput,
      stderr: errorOutput,
    };
  }
}

describe("YAML Validator Integration Tests", () => {
  beforeAll(() => {
    // Create temporary directory for test fixtures
    testDir = `/tmp/yaml-validator-test-${Date.now()}`;
    if (!fs.existsSync(testDir)) {
      fs.mkdirSync(testDir, { recursive: true });
    }
  });

  afterAll(() => {
    // Clean up test fixtures
    if (fs.existsSync(testDir)) {
      fs.rmSync(testDir, { recursive: true, force: true });
    }
  });

  describe("Basic Validation - Single Valid File", () => {
    test("should return exit code 0 for valid YAML file", async () => {
      const content = `
name: Test App
version: 1.0.0
description: A test configuration
features:
  - logging
  - validation
`;
      const filePath = createTestFile("valid.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("valid.yaml");
      expect(result.stdout).toContain("passed");
    });

    test("should display success indicator for valid file", async () => {
      const content = `
database:
  host: localhost
  port: 5432
  credentials:
    user: admin
    password: secret
`;
      const filePath = createTestFile("valid-nested.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("✓");
    });
  });

  describe("Basic Validation - Single Invalid File", () => {
    test("should return exit code 1 for YAML with indentation error", async () => {
      const content = `
name: Test
config:
  key1: value1
   key2: value2
`;
      const filePath = createTestFile("invalid-indent.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("✗");
    });

    test("should report unclosed quote error", async () => {
      const content = `
name: "Unclosed Quote
version: 1.0.0
`;
      const filePath = createTestFile("invalid-quote.yaml", content);

      const result = await runValidator([filePath]);

