/**
 * Helper to run the yaml:validate script via bun command.
 * Returns { exitCode, stdout, stderr }.
 */
async function runValidator(args: string[]): Promise<{
  exitCode: number;
  stdout: string;
  stderr: string;
}> {
  try {
    const cmd = `bun run yaml:validate ${args.join(" ")}`;
    const output = await $`bun run yaml:validate ${args}`.text();

    return {
      exitCode: 0,
      stdout: output,
      stderr: "",
    };
  } catch (error) {
    // Bun throws on non-zero exit; we catch and extract details
    const errorOutput =
      error instanceof Error ? error.message : String(error);

    // Try to parse exit code from error message
    const exitCodeMatch = errorOutput.match(/exited with code (\d+)/);
    const exitCode = exitCodeMatch ? parseInt(exitCodeMatch[1], 10) : 1;

    return {
      exitCode,
      stdout: errorOutput,
      stderr: errorOutput,
    };
  }
}

input.new_string:
/**
 * Helper to run the yaml:validate script via bun command.
 * Returns { exitCode, stdout, stderr }.
 */
async function runValidator(args: string[]): Promise<{
  exitCode: number;
  stdout: string;
  stderr: string;
}> {
  // Use spawn to capture both stdout and stderr properly
  const proc = Bun.spawn(["bun", "run", "yaml:validate", ...args], {
    stdout: "pipe",
    stderr: "pipe",
  });

  const stdout = await new Response(proc.stdout).text();
  const stderr = await new Response(proc.stderr).text();
  const exitCode = await proc.exited;

  return {
    exitCode,
    stdout,
    stderr,
  };
}

