/**
 * YAML Parser - Basic YAML syntax validation module
 *
 * This module provides lightweight YAML syntax validation using a hand-rolled parser.
 * It detects common YAML errors including:
 * - Indentation errors (tabs, inconsistent depths, unexpected changes)
 * - Syntax errors (unclosed quotes, unbalanced brackets/braces, malformed key-value pairs)
 * - Structure errors (invalid YAML keys, missing colons)
 *
 * The parser tokenizes input line-by-line and validates against YAML structural rules.
 * It returns structured error information with file path, line number, column, and message.
 *
 * Limitations:
 * - Advanced YAML features (anchors/aliases, custom tags) are not supported
 * - Schema validation is not supported (basic syntax only)
 * - Complex nested structures may have edge cases
 */

/**
 * Represents a single YAML validation error.
 */
export type YAMLError = {
  file: string;
  line: number;
  column: number;
  type: "syntax" | "indentation" | "structure";
  message: string;
};

/**
 * Represents the result of validating a single YAML file.
 */
export type ValidationResult = {
  file: string;
  valid: boolean;
  errors: YAMLError[];
};

/**
 * Validates YAML content for syntax correctness and structural integrity.
 *
 * Algorithm:
 * 1. Normalize line endings (CRLF -> LF)
 * 2. Split content into lines
 * 3. Track indentation state using a stack of indentation levels
 * 4. For each line:
 *    - Skip empty lines and comments (lines starting with #)
 *    - Validate indentation (spaces only, consistent depth)
 *    - Parse key-value pairs (check for colons, quotes)
 *    - Check for balanced brackets/braces
 * 5. Return structured validation result with accurate line/column numbers (1-indexed)
 *
 * @param content - The YAML file content as a string
 * @param filePath - The file path for error reporting
 * @returns ValidationResult with valid flag and errors array
 */
export function validateYAML(
  content: string,
  filePath: string
): ValidationResult {
  const errors: YAMLError[] = [];

  // Normalize line endings
  const normalized = content.replace(/\r\n/g, "\n");
  const lines = normalized.split("\n");

  // Track indentation state
  const indentStack: number[] = [0]; // Start with base indentation level 0
  let bracketStack: string[] = []; // Track open brackets/braces/parentheses

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const lineNumber = lineNum + 1; // 1-indexed for user display

    // Skip empty lines
    if (line.trim().length === 0) {
      continue;
    }

    // Skip comments
    if (line.trim().startsWith("#")) {
      continue;
    }

    // Check for tabs (YAML should use spaces)
    if (line.includes("\t")) {
      errors.push({
        file: filePath,
        line: lineNumber,
        column: line.indexOf("\t") + 1,
        type: "indentation",
        message: "YAML does not support tabs; use spaces only",
      });
      continue;
    }

    // Calculate indentation
    const leadingSpaces = line.match(/^( *)/)?.[0]?.length ?? 0;
    const trimmedLine = line.trim();

    // Validate indentation consistency
    const currentIndent = indentStack[indentStack.length - 1];
    const indentChange = leadingSpaces - currentIndent;

    // Indentation should increase or decrease by consistent amounts (usually 2 spaces)
    if (indentChange > 0) {
      // Indentation increased - allow reasonable increase (1-8 spaces typically)
      if (indentChange > 8) {
        errors.push({
          file: filePath,
          line: lineNumber,
          column: leadingSpaces + 1,
          type: "indentation",
          message: `Unexpected indentation increase of ${indentChange} spaces`,
        });
        continue;
      }
      indentStack.push(leadingSpaces);
    } else if (indentChange < 0) {
      // Indentation decreased - pop stack until we find matching level
      while (
        indentStack.length > 1 &&
        indentStack[indentStack.length - 1] > leadingSpaces
      ) {
        indentStack.pop();
      }
      // Verify we found matching indentation level
      if (indentStack[indentStack.length - 1] !== leadingSpaces) {
        errors.push({
          file: filePath,
          line: lineNumber,
          column: leadingSpaces + 1,
          type: "indentation",
          message: `Inconsistent indentation; expected multiple of base indent`,
        });
        continue;
      }
    }

    // Validate syntax: check for balanced quotes and brackets
    const quoteError = validateQuotesAndBrackets(trimmedLine, lineNumber, filePath);
    if (quoteError) {
      errors.push(quoteError);
      continue;
    }

    // Validate key-value pair structure if line contains colons
    if (trimmedLine.includes(":")) {
      const keyValueError = validateKeyValuePair(trimmedLine, lineNumber, filePath);
      if (keyValueError) {
        errors.push(keyValueError);
      }
    }
  }

  return {
    file: filePath,
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Validates quotes and bracket balancing in a line.
 * Returns an error if quotes are unclosed or brackets are unbalanced.
 */
function validateQuotesAndBrackets(
  line: string,
  lineNumber: number,
  filePath: string
): YAMLError | null {
  const stack: string[] = [];
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    // Handle escape sequences in quoted strings
    if (prevChar === "\\") {
      continue; // Skip escaped characters
    }

    // Toggle quote states
    if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    }

    // Only check brackets outside of quoted strings
    if (!inSingleQuote && !inDoubleQuote) {
      if (char === "{" || char === "[" || char === "(") {
        stack.push(char);
      } else if (char === "}") {
        if (stack.length === 0 || stack[stack.length - 1] !== "{") {
          return {
            file: filePath,
            line: lineNumber,
            column: i + 1,
            type: "syntax",
            message: "Unbalanced closing brace }",
          };
        }
        stack.pop();
      } else if (char === "]") {
        if (stack.length === 0 || stack[stack.length - 1] !== "[") {
          return {
            file: filePath,
            line: lineNumber,
            column: i + 1,
            type: "syntax",
            message: "Unbalanced closing bracket ]",
          };
        }
        stack.pop();
      } else if (char === ")") {
        if (stack.length === 0 || stack[stack.length - 1] !== "(") {
          return {
            file: filePath,
            line: lineNumber,
            column: i + 1,
            type: "syntax",
            message: "Unbalanced closing parenthesis )",
          };
        }
        stack.pop();
      }
    }
  }

  // Check for unclosed quotes
  if (inSingleQuote) {
    return {
      file: filePath,
      line: lineNumber,
      column: line.length + 1,
      type: "syntax",
      message: "Unclosed single-quoted string",
    };
  }
  if (inDoubleQuote) {
    return {
      file: filePath,
      line: lineNumber,
      column: line.length + 1,
      type: "syntax",
      message: "Unclosed double-quoted string",
    };
  }

  // Check for unclosed brackets
  if (stack.length > 0) {
    const unclosed = stack[stack.length - 1];
    const closingChar = unclosed === "{" ? "}" : unclosed === "[" ? "]" : ")";
    return {
      file: filePath,
      line: lineNumber,
      column: line.length + 1,
      type: "syntax",
      message: `Unclosed bracket/brace; expected ${closingChar}`,
    };
  }

  return null;
}

/**
 * Validates key-value pair structure.
 * YAML key-value pairs should have format: key: value
 * Returns an error if structure is invalid.
 */
function validateKeyValuePair(
  line: string,
  lineNumber: number,
  filePath: string
): YAMLError | null {
  // Find the first colon not inside quotes
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let colonPos = -1;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const prevChar = i > 0 ? line[i - 1] : "";

    // Skip escaped characters
    if (prevChar === "\\") {
      continue;
    }

    // Track quote states
    if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    }

    // Find unquoted colon
    if (char === ":" && !inSingleQuote && !inDoubleQuote) {
      colonPos = i;
      break;
    }
  }

  // If there's a colon, ensure there's something before it
  if (colonPos >= 0) {
    const keyPart = line.substring(0, colonPos).trim();
    if (keyPart.length === 0) {
      return {
        file: filePath,
        line: lineNumber,
        column: colonPos + 1,
        type: "structure",
        message: "Key-value pair missing key before colon",
      };
    }

    // Check for invalid key characters (keys shouldn't have certain symbols)
    if (
      keyPart.startsWith("-") &&
      keyPart !== "-" &&
      keyPart[1] !== " " &&
      keyPart[1] !== "\t"
    ) {
      // This is OK for list items
    }
  }

  return null;
}

