      expect(result.errors).toHaveLength(0);
    });

    test("File with only comments", () => {
      const yaml = "# Comment 1\n# Comment 2\n# Comment 3";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("File with empty lines and comments", () => {
      const yaml = "\n# Comment\n\nkey: value\n\n";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("List items", () => {
      const yaml = "items:\n  - item1\n  - item2\n  - item3";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("Inline objects", () => {
      const yaml = "config: {name: test, value: 123}";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

