    test("Quoted string containing colons", () => {
      const yaml = 'url: "http://example.com:8080"';
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("Escape sequences in quoted strings", () => {
      const yaml = 'text: "line with \\" escaped quote"';
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("Large file with valid structure", () => {
      let yaml = "";
      for (let i = 0; i < 1000; i++) {
        yaml += `key${i}: value${i}\n`;
      }
      const result = validateYAML(yaml, "large.yaml");
      expect(result.valid).toBe(true);
    });

    test("Whitespace-only lines are skipped", () => {
      const yaml = "key: value\n   \n  \nfoo: bar";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("Deep nesting with consistent indentation", () => {
      const yaml =
        "level1:\n  level2:\n    level3:\n      level4:\n        key: value";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });
  });

  describe("Validation Result Structure", () => {
    test("Returns ValidationResult with correct structure for valid YAML", () => {
      const result = validateYAML("key: value", "test.yaml");
      expect(result).toHaveProperty("file");
      expect(result).toHaveProperty("valid");
      expect(result).toHaveProperty("errors");
      expect(Array.isArray(result.errors)).toBe(true);
    });

    test("Valid flag is true when no errors", () => {
      const result = validateYAML("key: value", "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("Valid flag is false when errors present", () => {
      const result = validateYAML('key: "unclosed', "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });
});

