import { validateYAML } from "./src/yaml-parser.ts";

const tests = [
  { name: "Empty file", input: "", expectedValid: true },
  { name: "Only comments", input: "# comment1\n# comment2", expectedValid: true },
  { name: "Simple key-value", input: "key: value", expectedValid: true },
  { name: "Nested structure", input: "parent:\n  child: value\n  other: data", expectedValid: true },
  { name: "Quoted string", input: 'key: "quoted value"', expectedValid: true },
  { name: "Single quotes", input: "key: 'single quoted'", expectedValid: true },
  { name: "Quoted key with colon", input: 'key: "value: with: colons"', expectedValid: true },
  { name: "Escaped quote in double quotes", input: 'key: "value with \\" quote"', expectedValid: true },
  { name: "Escaped quote in single quotes", input: "key: 'value with \\' quote'", expectedValid: true },
  { name: "Tab character", input: "\tkey: value", expectedValid: false },
  { name: "Unclosed double quote", input: 'key: "unclosed', expectedValid: false },
  { name: "Unclosed single quote", input: "key: 'unclosed", expectedValid: false },
  { name: "Unbalanced bracket", input: "key: [1, 2, 3", expectedValid: false },
  { name: "Unbalanced brace", input: "key: {a: 1, b: 2", expectedValid: false },
  { name: "Unbalanced paren", input: "key: (1, 2, 3", expectedValid: false },
  { name: "CRLF line endings", input: "key: value\r\nfoo: bar\r\n", expectedValid: true },
  { name: "Large indent jump (>8)", input: "key:\n          value: too much", expectedValid: false },
  { name: "List syntax", input: "items:\n  - item1\n  - item2", expectedValid: true },
  { name: "Inline list", input: "items: [1, 2, 3]", expectedValid: true },
  { name: "Inline object", input: "data: {a: 1, b: 2}", expectedValid: true },
];

let passed = 0;
let failed = 0;

for (const test of tests) {
  const result = validateYAML(test.input, "test.yaml");
  const match = result.valid === test.expectedValid;

  if (match) {
    passed++;
  } else {
    failed++;
    console.log(`FAIL: ${test.name} - expected ${test.expectedValid}, got ${result.valid}`);
    if (result.errors.length > 0) {
      console.log(`  Error: ${result.errors[0].message}`);
    }
  }
}

console.log(`\nResults: ${passed} passed, ${failed} failed`);
EOF
bun run comprehensive_test.ts

