test("resolves glob pattern (*)", async () => {
  const file1 = join(tempDir, "glob1.yaml");
  const file2 = join(tempDir, "glob2.yaml");
  writeFileSync(file1, "key: value\n");
  writeFileSync(file2, "other: data\n");

  // Use a relative glob pattern from the test temp directory
  const pattern = tempDir + "/glob*.yaml";
  const resolved = await resolveFiles([pattern]);

  expect(resolved.length).toBe(2);
  expect(resolved.some((p) => p.includes("glob1.yaml"))).toBe(true);
  expect(resolved.some((p) => p.includes("glob2.yaml"))).toBe(true);
});

test("resolves recursive glob (**/*.yaml)", async () => {
  const subdir = join(tempDir, "recursive-test", "nested");
  mkdirSync(subdir, { recursive: true });
  const nestedFile = join(subdir, "config.yaml");
  writeFileSync(nestedFile, "key: value\n");

  // Use a recursive glob pattern starting from tempDir
  const pattern = tempDir + "/**/*.yaml";
  const resolved = await resolveFiles([pattern]);

  expect(resolved.length).toBeGreaterThan(0);
  expect(resolved.some((p) => p.includes("config.yaml"))).toBe(true);
});

