     1→/**
     2→ * YAML CLI - Command-line interface orchestration for YAML validation
     3→ *
     4→ * This module provides CLI functionality for the YAML validator, including:
     5→ * - File and glob pattern resolution using Bun.Glob
     6→ * - Batch file validation with graceful error handling
     7→ * - Output formatting with clear success/failure indicators
     8→ * - Summary generation for multiple file validation results
     9→ *
    10→ * The module orchestrates the validation workflow by accepting file patterns,
    11→ * expanding them via glob matching, reading files, validating content, and
    12→ * formatting results for console output.
    13→ */
    14→
    15→import { validateYAML, ValidationResult } from "./yaml-parser";
    16→
    17→/**
    18→ * Resolves file paths and glob patterns to concrete file paths.
    19→ *
    20→ * Uses Bun.Glob to expand glob patterns (*, **, ?) and deduplicates results.
    21→ * Supports mixed input of direct file paths and glob patterns.
    22→ *
    23→ * @param patterns - Array of file paths or glob patterns (e.g., ["config.yaml", "src/**\/*.yaml"])
    24→ * @returns Promise resolving to deduplicated array of file paths
    25→ * @throws Error if no files match the provided patterns
    26→ */
    27→export async function resolveFiles(patterns: string[]): Promise<string[]> {
    28→  const resolvedSet = new Set<string>();
    29→
    30→  for (const pattern of patterns) {
    31→    try {
    32→      // Check if pattern contains glob characters
    33→      if (pattern.includes("*") || pattern.includes("?")) {
    34→        // Use Bun.Glob for pattern expansion
    35→        const globber = new Bun.Glob(pattern);
    36→        for await (const file of globber.scan({ onlyFiles: true })) {
    37→          resolvedSet.add(file);
    38→        }
    39→      } else {
    40→        // Treat as direct file path
    41→        resolvedSet.add(pattern);
    42→      }
    43→    } catch (error) {
    44→      // Glob expansion failed - could be invalid pattern or no matches
    45→      // Continue with other patterns rather than failing completely
    46→      continue;
    47→    }
    48→  }
    49→
    50→  const resolved = Array.from(resolvedSet).sort();
    51→
    52→  if (resolved.length === 0) {
    53→    throw new Error(
    54→      `No files matched patterns: ${patterns.join(", ")}`
    55→    );
    56→  }
    57→
    58→  return resolved;
    59→}
