    61→/**
    62→ * Validates an array of YAML files and returns validation results.
    63→ *
    64→ * Reads each file using Bun.file() and calls validateYAML() for content validation.
    65→ * Handles file read errors gracefully (missing files, permission errors) and
    66→ * continues processing remaining files.
    67→ *
    68→ * @param filePaths - Array of file paths to validate
    69→ * @returns Promise resolving to array of ValidationResult objects (one per file)
    70→ */
    71→export async function validateFiles(filePaths: string[]): Promise<ValidationResult[]> {
    72→  const results: ValidationResult[] = [];
    73→
    74→  for (const filePath of filePaths) {
    75→    try {
    76→      // Read file using Bun.file()
    77→      const file = Bun.file(filePath);
    78→      const exists = await file.exists();
    79→
    80→      if (!exists) {
    81→        // File does not exist - create error result
    82→        results.push({
    83→          file: filePath,
    84→          valid: false,
    85→          errors: [
    86→            {
    87→              file: filePath,
    88→              line: 0,
    89→              column: 0,
    90→              type: "syntax",
    91→              message: "File not found",
    92→            },
    93→          ],
    94→        });
    95→        continue;
    96→      }
    97→
    98→      const content = await file.text();
    99→      const result = validateYAML(content, filePath);
   100→      results.push(result);
   101→    } catch (error) {
   102→      // Handle file read errors (permission denied, I/O errors, etc.)
   103→      const errorMessage =
   104→        error instanceof Error ? error.message : String(error);
   105→
   106→      results.push({
   107→        file: filePath,
   108→        valid: false,
   109→        errors: [
   110→          {
   111→            file: filePath,
   112→            line: 0,
   113→            column: 0,
   114→            type: "syntax",
   115→            message: `Error reading file: ${errorMessage}`,
   116→          },
   117→        ],
   118→      });
   119→    }
   120→  }
   121→
   122→  return results;
   123→}
   124→
   125→/**
   126→ * Formats validation results for console output.
   127→ *
   128→ * Produces human-readable output with:
   129→ * - Success indicator (✓) for valid files
   130→ * - Error indicator (✗) for invalid files
   131→ * - Detailed error information (line, column, message) for each error
   132→ *
   133→ * @param results - Array of ValidationResult objects from validateFiles()
   134→ * @returns Formatted string ready for console output
   135→ */
   136→export function formatOutput(results: ValidationResult[]): string {
   137→  const lines: string[] = [];
   138→
   139→  for (const result of results) {
   140→    if (result.valid) {
   141→      // Valid file - show success indicator
   142→      lines.push(`✓ ${result.file}`);
   143→    } else {
   144→      // Invalid file - show error indicator and details
   145→      lines.push(`✗ ${result.file}`);
   146→      for (const error of result.errors) {
   147→        lines.push(`  Line ${error.line}, Column ${error.column}: ${error.message}`);
   148→      }
   149→    }
   150→  }
   151→
   152→  return lines.join("\n");
   153→}
   154→
   155→/**
   156→ * Generates a summary of validation results.
   157→ *
   158→ * Counts passed (valid) and failed (invalid) files and returns summary counts.
   159→ *
   160→ * @param results - Array of ValidationResult objects from validateFiles()
   161→ * @returns Object with passed, failed, and total file counts
   162→ */
   163→export function getSummary(
   164→  results: ValidationResult[]
   165→): { passed: number; failed: number; total: number } {
   166→  const passed = results.filter((r) => r.valid).length;
   167→  const failed = results.filter((r) => !r.valid).length;
   168→
   169→  return {
   170→    passed,
   171→    failed,
   172→    total: results.length,
   173→  };
   174→}
