/**
 * YAML Validator - Entry point script for validating YAML files
 *
 * Usage:
 *   bun run src/yaml-validate.ts <file-or-pattern> [additional-files-or-patterns...]
 *
 * Examples:
 *   bun run src/yaml-validate.ts config.yaml
 *   bun run src/yaml-validate.ts config/*.yaml
 *   bun run src/yaml-validate.ts src/**/*.yml config.yaml
 *
 * Exit Codes:
 *   0 - All provided files are valid YAML
 *   1 - One or more files have validation errors
 *
 * The script:
 * 1. Parses command-line arguments to extract file paths and glob patterns
 * 2. Expands glob patterns to concrete file paths using resolveFiles()
 * 3. Validates all files using validateFiles()
 * 4. Formats and prints results to console
 * 5. Exits with appropriate code based on validation success
 */

import {
  resolveFiles,
  validateFiles,
  formatOutput,
  getSummary,
} from "./yaml-cli";

/**
 * Main entry point for the YAML validator.
 * Orchestrates the validation workflow and handles exit codes.
 */
async function main(): Promise<void> {
  // Extract file/pattern arguments from command line
  // argv[0] is the bun executable, argv[1] is the script path
  const args = process.argv.slice(2);

  // Validate that at least one argument was provided
  if (args.length === 0) {
    console.error("Usage: bun run yaml-validate.ts <file-or-pattern> [files...]");
    console.error("");
    console.error("Examples:");
    console.error("  bun run yaml-validate.ts config.yaml");
    console.error("  bun run yaml-validate.ts config/*.yaml");
    console.error("  bun run yaml-validate.ts src/**/*.yml config.yaml");
    process.exit(1);
  }

  try {
    // Resolve file patterns to concrete file paths
    const filePaths = await resolveFiles(args);

    // Validate all files
    const results = await validateFiles(filePaths);

    // Format and print output
    const formattedOutput = formatOutput(results);
    console.log(formattedOutput);

    // Print summary
    const summary = getSummary(results);
    console.log("");
    console.log(
      `Summary: ${summary.passed} passed, ${summary.failed} failed (${summary.total} files checked)`
    );

    // Exit with appropriate code
    const allValid = results.every((r) => r.valid);
    process.exit(allValid ? 0 : 1);
  } catch (error) {
    // Handle critical errors (e.g., no files matched patterns)
    const errorMessage =
      error instanceof Error ? error.message : String(error);
    console.error(`Error: ${errorMessage}`);
    process.exit(1);
  }
}

// Run the main function
main().catch((error) => {
  console.error(`Fatal error: ${error}`);
  process.exit(1);
});

