/**
 * Integration tests for the YAML validator command.
 *
 * These tests invoke the yaml:validate script via the `bun` command and verify:
 * - Exit code behavior (0 on success, 1 on failure)
 * - Output formatting and accuracy
 * - Glob pattern expansion and file resolution
 * - Error reporting with line/column information
 *
 * Tests use temporary YAML files created during test setup and cleaned up after.
 */

import { describe, test, expect, beforeAll, afterAll } from "bun:test";
import { $ } from "bun";
import fs from "fs";
import path from "path";

/**
 * Temporary directory for test fixtures.
 * Created before tests, cleaned up after.
 */
let testDir: string;

/**
 * Helper to create a temporary test file with YAML content.
 */
function createTestFile(
  filename: string,
  content: string
): string {
  const filePath = path.join(testDir, filename);
  const dirPath = path.dirname(filePath);

  // Create subdirectories if needed
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }

  fs.writeFileSync(filePath, content);
  return filePath;
}

/**
 * Helper to run the yaml:validate script via bun command.
 * Returns { exitCode, stdout, stderr }.
 */
async function runValidator(args: string[]): Promise<{
  exitCode: number;
  stdout: string;
  stderr: string;
}> {
  try {
    const cmd = `bun run yaml:validate ${args.join(" ")}`;
    const output = await $`bun run yaml:validate ${args}`.text();

    return {
      exitCode: 0,
      stdout: output,
      stderr: "",
    };
  } catch (error) {
    // Bun throws on non-zero exit; we catch and extract details
    const errorOutput =
      error instanceof Error ? error.message : String(error);

    // Try to parse exit code from error message
    const exitCodeMatch = errorOutput.match(/exited with code (\d+)/);
    const exitCode = exitCodeMatch ? parseInt(exitCodeMatch[1], 10) : 1;

    return {
      exitCode,
      stdout: errorOutput,
      stderr: errorOutput,
    };
  }
}

describe("YAML Validator Integration Tests", () => {
  beforeAll(() => {
    // Create temporary directory for test fixtures
    testDir = `/tmp/yaml-validator-test-${Date.now()}`;
    if (!fs.existsSync(testDir)) {
      fs.mkdirSync(testDir, { recursive: true });
    }
  });

  afterAll(() => {
    // Clean up test fixtures
    if (fs.existsSync(testDir)) {
      fs.rmSync(testDir, { recursive: true, force: true });
    }
  });

  describe("Basic Validation - Single Valid File", () => {
    test("should return exit code 0 for valid YAML file", async () => {
      const content = `
name: Test App
version: 1.0.0
description: A test configuration
features:
  - logging
  - validation
`;
      const filePath = createTestFile("valid.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("valid.yaml");
      expect(result.stdout).toContain("passed");
    });

    test("should display success indicator for valid file", async () => {
      const content = `
database:
  host: localhost
  port: 5432
  credentials:
    user: admin
    password: secret
`;
      const filePath = createTestFile("valid-nested.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("✓");
    });
  });

  describe("Basic Validation - Single Invalid File", () => {
    test("should return exit code 1 for YAML with indentation error", async () => {
      const content = `
name: Test
config:
  key1: value1
   key2: value2
`;
      const filePath = createTestFile("invalid-indent.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("✗");
    });

    test("should report unclosed quote error", async () => {
      const content = `
name: "Unclosed Quote
version: 1.0.0
`;
      const filePath = createTestFile("invalid-quote.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("✗");
      expect(result.stdout).toContain("quote");
    });

    test("should report malformed key-value pair", async () => {
      const content = `
valid_key: value
invalid_key value
another: ok
`;
      const filePath = createTestFile("invalid-kv.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("✗");
    });
  });

  describe("Multiple Files - Mixed Valid/Invalid", () => {
    test("should validate multiple files and return exit code 1 if any are invalid", async () => {
      const validContent = `
name: Valid App
version: 1.0.0
`;
      const invalidContent = `
name: Invalid App
config:
  key: value
 broken: indent
`;

      const validPath = createTestFile("multi-valid.yaml", validContent);
      const invalidPath = createTestFile("multi-invalid.yaml", invalidContent);

      const result = await runValidator([validPath, invalidPath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("valid.yaml");
      expect(result.stdout).toContain("invalid.yaml");
    });

    test("should return exit code 0 when all files are valid", async () => {
      const content1 = `
app: test
version: 1.0
`;
      const content2 = `
database:
  type: postgres
  port: 5432
`;

      const path1 = createTestFile("all-valid-1.yaml", content1);
      const path2 = createTestFile("all-valid-2.yaml", content2);

      const result = await runValidator([path1, path2]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Summary");
      expect(result.stdout).toContain("2 passed");
    });
  });

  describe("Glob Pattern Support", () => {
    test("should expand glob pattern and validate matching files", async () => {
      // Create multiple YAML files in a subdirectory
      const dir = path.join(testDir, "config");
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      const validContent = `
name: Config1
value: 123
`;

      fs.writeFileSync(path.join(dir, "app.yaml"), validContent);
      fs.writeFileSync(path.join(dir, "db.yaml"), validContent);

      // Note: We use the absolute path pattern for glob
      const pattern = `${dir}/*.yaml`;

      const result = await runValidator([pattern]);

      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("Summary");
      expect(result.stdout).toContain("2 passed");
    });
  });

  describe("Output Formatting", () => {
    test("should include summary line with pass/fail counts", async () => {
      const content = `
key: value
nested:
  item: test
`;
      const filePath = createTestFile("summary-test.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.stdout).toContain("Summary:");
      expect(result.stdout).toContain("passed");
      expect(result.stdout).toContain("failed");
    });

    test("should report error with line and column information", async () => {
      const content = `
valid: line1
another: line2
 broken: line3
extra: line4
`;
      const filePath = createTestFile("error-location.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
      // Error should mention line/column where indentation is wrong
      expect(result.stdout).toMatch(/[Ll]ine\s*[0-9]+/);
    });
  });

  describe("Error Handling", () => {
    test("should show usage when no arguments provided", async () => {
      const result = await runValidator([]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("Usage");
    });

    test("should handle missing files gracefully", async () => {
      const result = await runValidator(["/nonexistent/path/to/file.yaml"]);

      expect(result.exitCode).toBe(1);
      // Should show error message, not crash
      expect(result.stdout.length > 0 || result.stderr.length > 0).toBe(true);
    });
  });

  describe("Edge Cases", () => {
    test("should handle empty YAML file as valid", async () => {
      const filePath = createTestFile("empty.yaml", "");

      const result = await runValidator([filePath]);

      // Empty file is technically valid YAML
      expect(result.exitCode).toBe(0);
    });

    test("should handle YAML with only comments", async () => {
      const content = `
# This is a comment
# Another comment
# Just comments, no content
`;
      const filePath = createTestFile("comments-only.yaml", content);

      const result = await runValidator([filePath]);

      // File with only comments should be valid
      expect(result.exitCode).toBe(0);
    });

    test("should handle YAML with Windows line endings (CRLF)", async () => {
      const content = "name: Test\r\nversion: 1.0\r\n";
      const filePath = createTestFile("crlf.yaml", content);

      const result = await runValidator([filePath]);

      // Should normalize CRLF and validate correctly
      expect(result.exitCode).toBe(0);
    });

    test("should detect tabs in indentation as error", async () => {
      const content = "config:\n\t key: value\n";
      const filePath = createTestFile("tabs.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
      expect(result.stdout).toContain("✗");
    });
  });

  describe("Script Integration with package.json", () => {
    test("yaml:validate script should be registered and functional", async () => {
      const content = `
test: data
nested:
  item: value
`;
      const filePath = createTestFile("script-test.yaml", content);

      // Run using the registered script
      const result = await runValidator([filePath]);

      // Script should execute successfully
      expect(result.exitCode).toBe(0);
    });
  });

  describe("Complex Real-World Scenarios", () => {
    test("should validate deeply nested structure", async () => {
      const content = `
server:
  database:
    primary:
      host: db1.example.com
      port: 5432
      replica:
        host: db2.example.com
        port: 5432
        connection_pool:
          min: 10
          max: 100
          idle_timeout: 300
`;
      const filePath = createTestFile("deep-nested.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(0);
    });

    test("should detect misaligned keys in nested structures", async () => {
      const content = `
server:
  database:
    host: localhost
   port: 5432
`;
      const filePath = createTestFile("misaligned.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(1);
    });

    test("should validate YAML with quoted strings containing special chars", async () => {
      const content = `
message: "This is a message: with colons"
description: "And quotes \\"inside\\" the string"
path: "C:\\\\Users\\\\admin\\\\config.yaml"
`;
      const filePath = createTestFile("quoted-special.yaml", content);

      const result = await runValidator([filePath]);

      expect(result.exitCode).toBe(0);
    });
  });
});

