     1→/**
     2→ * YAML Validator - Entry point script for validating YAML files
     3→ *
     4→ * Usage:
     5→ *   bun run src/yaml-validate.ts <file-or-pattern> [additional-files-or-patterns...]
     6→ *
     7→ * Examples:
     8→ *   bun run src/yaml-validate.ts config.yaml
     9→ *   bun run src/yaml-validate.ts config/path/*.yaml
    10→ *   bun run src/yaml-validate.ts src/path/to/yaml/*.yml config.yaml
    11→ *
    12→ * Exit Codes:
    13→ *   0 - All provided files are valid YAML
    14→ *   1 - One or more files have validation errors
    15→ *
    16→ * The script:
    17→ * 1. Parses command-line arguments to extract file paths and glob patterns
    18→ * 2. Expands glob patterns to concrete file paths using resolveFiles()
    19→ * 3. Validates all files using validateFiles()
    20→ * 4. Formats and prints results to console
    21→ * 5. Exits with appropriate code based on validation success
    22→ */
    23→
    24→import {
    25→  resolveFiles,
    26→  validateFiles,
    27→  formatOutput,
    28→  getSummary,
    29→} from "./yaml-cli";
    30→
    31→/**
    32→ * Main entry point for the YAML validator.
    33→ * Orchestrates the validation workflow and handles exit codes.
    34→ */
    35→async function main(): Promise<void> {
    36→  // Extract file/pattern arguments from command line
    37→  // argv[0] is the bun executable, argv[1] is the script path
    38→  const args = process.argv.slice(2);
    39→
    40→  // Validate that at least one argument was provided
    41→  if (args.length === 0) {
    42→    console.error("Usage: bun run yaml-validate.ts <file-or-pattern> [files...]");
    43→    console.error("");
    44→    console.error("Examples:");
    45→    console.error("  bun run yaml-validate.ts config.yaml");
    46→    console.error("  bun run yaml-validate.ts config/*.yaml");
    47→    console.error("  bun run yaml-validate.ts src/**/*.yml config.yaml");
    48→    process.exit(1);
    49→  }
    50→
    51→  try {
    52→    // Resolve file patterns to concrete file paths
    53→    const filePaths = await resolveFiles(args);
    54→
    55→    // Validate all files
    56→    const results = await validateFiles(filePaths);
    57→
    58→    // Format and print output
    59→    const formattedOutput = formatOutput(results);
    60→    console.log(formattedOutput);
    61→
    62→    // Print summary
    63→    const summary = getSummary(results);
    64→    console.log("");
    65→    console.log(
    66→      `Summary: ${summary.passed} passed, ${summary.failed} failed (${summary.total} files checked)`
    67→    );
    68→
    69→    // Exit with appropriate code
    70→    const allValid = results.every((r) => r.valid);
    71→    process.exit(allValid ? 0 : 1);
    72→  } catch (error) {
    73→    // Handle critical errors (e.g., no files matched patterns)
    74→    const errorMessage =
    75→      error instanceof Error ? error.message : String(error);
    76→    console.error(`Error: ${errorMessage}`);
    77→    process.exit(1);
    78→  }
    79→}
    80→
    81→// Run the main function
    82→main().catch((error) => {
    83→  console.error(`Fatal error: ${error}`);
    84→  process.exit(1);
    85→});
